import React, { useState, useEffect } from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import { useSelector, useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';
import { setWallet } from '../redux/slices/userSlice';
import { toast } from 'react-toastify';

const WalletPage = () => {
  const { isAuthenticated } = useSelector((state) => state.auth);
  const { wallet } = useSelector((state) => state.user);
  const navigate = useNavigate();
  const dispatch = useDispatch();

  const [addAmount, setAddAmount] = useState('');
  const [loading, setLoading] = useState(false);
  const [paymentHistory, setPaymentHistory] = useState([]);

  useEffect(() => {
    if (!isAuthenticated) {
      navigate('/login');
      return;
    }

    fetchWalletData();
  }, [isAuthenticated, navigate]);

  const fetchWalletData = async () => {
    try {
      const walletRes = await api.get('/users/wallet');
      const historyRes = await api.get('/payments/history');

      dispatch(setWallet(walletRes.data.wallet));
      setPaymentHistory(historyRes.data.payments || []);
    } catch (error) {
      toast.error('Failed to load wallet data');
    }
  };

  const handleAddMoney = async (e) => {
    e.preventDefault();
    if (!addAmount || addAmount <= 0) {
      toast.warning('Please enter a valid amount');
      return;
    }

    setLoading(true);
    try {
      const response = await api.post('/payments/wallet/add-money', {
        amount: parseFloat(addAmount),
      });

      // Handle Razorpay payment here
      toast.success('Payment initiated');
      setAddAmount('');
      fetchWalletData();
    } catch (error) {
      toast.error('Failed to add money');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-gray-50">
      <Header />

      <main className="flex-1 p-4 sm:p-6 lg:p-8">
        <div className="max-w-7xl mx-auto">
          <h1 className="text-3xl font-bold mb-8">My Wallet</h1>

          {/* Balance Card */}
          <div className="bg-gradient-to-r from-blue-600 to-blue-800 text-white rounded-lg p-8 mb-8 shadow-lg">
            <p className="text-blue-100 mb-2">Wallet Balance</p>
            <h2 className="text-5xl font-bold mb-4">₹{wallet.walletBalance || 0}</h2>
            <p className="text-blue-100">Available for rides</p>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Add Money Section */}
            <div className="lg:col-span-1">
              <div className="bg-white rounded-lg shadow-md p-6">
                <h3 className="text-xl font-bold mb-4">Add Money</h3>
                <form onSubmit={handleAddMoney} className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Amount (₹)
                    </label>
                    <input
                      type="number"
                      value={addAmount}
                      onChange={(e) => setAddAmount(e.target.value)}
                      placeholder="500"
                      min="100"
                      max="50000"
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-600"
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-2">
                    {[500, 1000, 2000, 5000].map((amount) => (
                      <button
                        key={amount}
                        type="button"
                        onClick={() => setAddAmount(amount.toString())}
                        className="px-3 py-2 border border-blue-600 text-blue-600 rounded-lg hover:bg-blue-50 transition"
                      >
                        ₹{amount}
                      </button>
                    ))}
                  </div>

                  <button
                    type="submit"
                    disabled={loading}
                    className="w-full bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 font-bold transition"
                  >
                    {loading ? 'Processing...' : 'Add Money'}
                  </button>
                </form>
              </div>
            </div>

            {/* Transaction History */}
            <div className="lg:col-span-2">
              <div className="bg-white rounded-lg shadow-md p-6">
                <h3 className="text-xl font-bold mb-4">Transaction History</h3>
                {paymentHistory.length === 0 ? (
                  <p className="text-gray-600 text-center py-8">No transactions yet</p>
                ) : (
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead className="border-b border-gray-200">
                        <tr>
                          <th className="text-left py-2 px-4">Date</th>
                          <th className="text-left py-2 px-4">Type</th>
                          <th className="text-left py-2 px-4">Amount</th>
                          <th className="text-left py-2 px-4">Status</th>
                        </tr>
                      </thead>
                      <tbody>
                        {paymentHistory.map((payment) => (
                          <tr key={payment._id} className="border-b border-gray-200 hover:bg-gray-50">
                            <td className="py-3 px-4">
                              {new Date(payment.transactionDate).toLocaleDateString()}
                            </td>
                            <td className="py-3 px-4">{payment.paymentMethod}</td>
                            <td className="py-3 px-4 font-bold">₹{payment.amount}</td>
                            <td className="py-3 px-4">
                              <span
                                className={`px-2 py-1 rounded-full text-xs font-medium ${
                                  payment.paymentStatus === 'completed'
                                    ? 'bg-green-100 text-green-800'
                                    : 'bg-yellow-100 text-yellow-800'
                                }`}
                              >
                                {payment.paymentStatus}
                              </span>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </main>

      <Footer />
    </div>
  );
};

export default WalletPage;
